namespace ghidra.app.plugin.core.label;

using ghidra.app.services;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util;



using docking;

public class LabelHistoryDialog : DialogComponentProvider, LabelHistoryListener {
	private PluginTool tool;

	public LabelHistoryDialog(PluginTool tool, Program program, Address addr,
			List<LabelHistory> list) : base((addr != null) ? "Show Label History for " + addr : "Show Label History", true)
    {
		this.tool = tool;
		addWorkPanel(new LabelHistoryPanel(program, list, null));
		initialize();
	}

	public LabelHistoryDialog(PluginTool tool, Program program, string title,
			List<LabelHistory> list) : base(title, true)
    {
		this.tool = tool;
		addWorkPanel(new LabelHistoryPanel(program, list, this));
		initialize();
	}

	private void initialize() {
		addDismissButton();
		setHelpLocation(new HelpLocation(HelpTopics.LABEL, "Show_Label_History"));
	}

	/* @Override */
	public void addressSelected(Program program, Address addr) {
		GoToService service = tool.getService(typeof(GoToService));
		if (service != null) {
			service.goTo(new CodeUnitLocation(program, addr, null, 0, 0, 0));
		}
	}
}
